// Supabase Edge Function (Deno). Authoritative game server.
// core.js is generated by `npm run build:edge` from src/server/core.ts (same code the tests run).
// deno-lint-ignore-file no-explicit-any
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';
import * as core from './core.js';

const url = Deno.env.get('SUPABASE_URL')!;
const service = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const FOUNDER_EMAIL = (Deno.env.get('FOUNDER_EMAIL') ?? '').toLowerCase();
const db = createClient(url, service, { auth: { persistSession: false } });
const cors = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type' };
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { ...cors, 'Content-Type': 'application/json' } });
const chatTimes = new Map<string, number[]>(); // per-instance; DB check below is the real limit

async function loadWorld(): Promise<{ state: any; version: number }> {
  const { data } = await db.from('world_state').select('state, version').eq('id', 1).maybeSingle();
  if (data) return { state: data.state, version: data.version };
  const state = core.createWorld(Math.floor(Math.random() * 1e9), Date.now());
  await db.from('world_state').insert({ id: 1, state, version: 0 });
  return { state, version: 0 };
}
/** read → mutate → compare-and-swap commit, retried on conflict */
async function mutate<T>(f: (w: any) => T): Promise<T> {
  for (let i = 0; i < 5; i++) {
    const { state, version } = await loadWorld();
    const r = f(state);
    const { data: ok } = await db.rpc('commit_world', { new_state: state, expected: version });
    if (ok) return r;
  }
  throw new Error('Dünya meşgul, tekrar deneyin.');
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  try {
    const body = await req.json();
    const now = Date.now();
    if (body.op === 'candidates') {
      const { data: okAccess } = await db.rpc('check_access', { pw: String(body.access ?? '') });
      if (!okAccess) return json({ error: 'Giriş şifresi yanlış.' });
      const { state } = await loadWorld();
      return json(core.candidates(state));
    }
    if (body.op === 'register') {
      const { data: okAccess } = await db.rpc('check_access', { pw: String(body.access ?? '') });
      if (!okAccess) return json({ error: 'Giriş şifresi yanlış. Davet eden kişiden şifreyi isteyin.' });
      const email = String(body.email ?? '').trim().toLowerCase();
      const { data: created, error } = await db.auth.admin.createUser({ email, password: String(body.password ?? ''), email_confirm: true });
      if (error || !created.user) return json({ error: 'Hesap açılamadı (e-posta kayıtlı ya da şifre çok kısa).' });
      const founder = !!FOUNDER_EMAIL && email === FOUNDER_EMAIL;
      const uid = created.user.id;
      let personId: string;
      try { personId = await mutate((w) => { core.register(w, uid, String(body.name ?? ''), body.prof, founder, now, founder ? null : body.takeOverId ?? null); return w.players[uid].personId; }); }
      catch (e) { await db.auth.admin.deleteUser(uid); return json({ error: String((e as Error).message) }); }
      await db.from('players').insert({ user_id: uid, person_id: personId, display_name: String(body.name ?? '').slice(0, 24), is_founder: founder });
      if (founder) await db.from('game_config').update({ founder_user: uid }).eq('id', 1);
      return json({});
    }
    // authenticated ops
    const token = (req.headers.get('Authorization') ?? '').replace('Bearer ', '');
    const { data: u } = await db.auth.getUser(token);
    if (!u.user) return json({ error: 'oturum yok' }, 401);
    const uid = u.user.id;
    const { data: pl } = await db.from('players').select('*').eq('user_id', uid).maybeSingle();
    if (!pl) return json(null);
    if (pl.banned) return json({ error: 'Sürgün edildiniz.' }, 403);
    switch (body.op) {
      case 'me': return json({ playerId: uid, founder: pl.is_founder });
      case 'heartbeat': {
        let due = false;
        const out = await mutate((w) => { const r = core.heartbeat(w, uid, now); due = r.snapshotDue; return { world: w, summary: r.summary }; });
        if (due) await db.rpc('snapshot_world', { force: false });
        return json(out);
      }
      case 'act': return json(await mutate((w) => core.act(w, uid, body.action, now)));
      case 'chat': {
        const since = new Date(now - 30_000).toISOString();
        const { count } = await db.from('messages').select('id', { count: 'exact', head: true }).eq('from_user', uid).gte('created_at', since);
        if ((count ?? 0) >= 5) return json({ error: 'Çok hızlı yazıyorsunuz; biraz bekleyin.' });
        const { state } = await loadWorld();
        const times = chatTimes.get(uid) ?? []; chatTimes.set(uid, times);
        const m = core.makeChat(state, uid, String(body.text ?? ''), body.to ?? null, times, now);
        if (typeof m === 'string') return json({ error: m });
        await db.from('messages').insert({ from_user: uid, from_person: m.fromPersonId, from_name: m.fromName, to_person: m.toPersonId, text: m.text });
        return json({});
      }
      case 'snapshots': {
        if (!pl.is_founder) return json([]);
        const { data } = await db.from('world_snapshots').select('id, created_at, day').order('created_at', { ascending: false });
        return json((data ?? []).map((s: any) => ({ id: String(s.id), at: Date.parse(s.created_at), day: s.day })));
      }
      case 'admin': {
        if (!pl.is_founder) return json({ msg: 'Yetkiniz yok.' }, 403);
        const r = body.req;
        if (r.t === 'setPassword') { if (String(r.password).length < 4) return json({ msg: 'En az 4 karakter.' }); await db.rpc('set_access_password', { pw: String(r.password) }); return json({ msg: 'Giriş şifresi değişti.' }); }
        if (r.t === 'snapshot') { await db.rpc('snapshot_world', { force: true }); return json({ msg: 'Yedek alındı.' }); }
        if (r.t === 'restoreSnapshot') {
          const { data: s } = await db.from('world_snapshots').select('state, day').eq('id', Number(r.id)).maybeSingle();
          if (!s) return json({ msg: 'Yedek yok.' });
          await mutate((w) => { const players = w.players; Object.assign(w, s.state); w.players = { ...w.players, ...players }; w.lastTickAt = now; });
          return json({ msg: `Gün ${s.day} yedeği geri yüklendi.` });
        }
        if (r.t === 'ban') await db.from('players').update({ banned: !!r.banned }).eq('user_id', r.playerId);
        return json({ msg: await mutate((w) => core.admin(w, r)) });
      }
    }
    return json({ error: 'bilinmeyen işlem' }, 400);
  } catch (e) {
    return json({ error: String((e as Error).message ?? e) }, 500);
  }
});
